from taf.ul.sc import perf
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.collectors.periodical_cmds import OneShotCmds, PeriodicalCmds


def clear_bts_stats():
    if tc.is_feature_enabled("collect_bts_stats"):
        for bts in tc.required_btss():
            if getattr(bts, 'ems', None):
                bts.clear_and_backup_pm_files()
                if tc.run_params['collect_bts_stats']['type'] == 'rtpm':
                    bts.ems.cli.clean_rtpm_stats()


def save_bts_stats():
    if tc.is_feature_enabled("collect_bts_stats") and tc.run_params['collect_bts_stats']['type'] == 'rtpm':
        for bts in tc.required_btss():
            if getattr(bts, 'ems', None):
                bts.ems.cli.parse_rtpm_stats(short=True, quiet=True)
        for bts in tc.required_btss():
            if getattr(bts, 'ems', None):
                bts.ems.cli.deactivate_rtpm_reporting()


def start_benchmark_stats_collecting():
    if tc.is_feature_enabled("collect_benchmark_stats"):
        for bts in tc.required_btss():
            period = tc.run_params['collect_benchmark_stats']['period']
            bts.start_benchmark_stats_collecting(period=period)


def stop_benchmark_stats_collecting():
    if tc.is_feature_enabled("collect_benchmark_stats"):
        for bts in tc.required_btss():
            bts.stop_benchmark_stats_collecting()


def start_dsp_stats_collecting():
    if tc.is_feature_enabled("collect_benchmark_stats->collect_dsp_stats"):
        for bts in tc.required_btss():
            bts.start_dsp_stats_collecting()


def stop_dsp_stats_collecting():
    if tc.is_feature_enabled("collect_benchmark_stats->collect_dsp_stats"):
        for bts in tc.required_btss():
            bts.stop_dsp_stats_collecting()


def start_fake_paging():
    if tc.is_feature_enabled("fake_paging"):
        paging_params = tc.run_params['fake_paging']['params']
        perf.tl.core.start_paging(params=paging_params)


def stop_fake_paging():
    if tc.is_feature_enabled("fake_paging"):
        paging_params = tc.run_params['fake_paging']['params']
        perf.tl.core.stop_paging(bts_names=paging_params.keys())


def start_test_recovery_observers():
    if tc.is_feature_enabled("test_recovery_observer"):
        action = 'break_test' if tc.run_params['test_recovery_observer']['break_test'] else 'test_recovery'
        perf.tl.ue.start_recovery_observers(action=action)
        perf.tl.core.start_recovery_observers(action=action,
                                              recovery_params={'restart_ue': False},
                                              after=[start_fake_paging])


def stop_test_recovery_observers():
    if tc.is_feature_enabled("test_recovery_observer"):
        perf.tl.ue.stop_recovery_observers()
        perf.tl.core.stop_recovery_observers()


def clear_sgw_and_pgw_stats():
    perf.tl.core.clear_sgw_and_pgw_stats()


def show_sgw_and_pgw_stats():
    perf.tl.core.get_sgw_and_pgw_stats()


def start_additional_cmds():
    add_cmds = tc.run_params['additional_cmds']
    if tc.is_feature_enabled("additional_cmds"):
        if add_cmds['cmds_before_scenario']:
            OneShotCmds(params=add_cmds['cmds_before_scenario']).start_cmds()
        if add_cmds['periodical_cmds']:
            PeriodicalCmds(params=add_cmds['periodical_cmds']).start_cmds()


def stop_additional_cmds():
    add_cmds = tc.run_params['additional_cmds']
    if tc.is_feature_enabled("additional_cmds"):
        if add_cmds['periodical_cmds']:
            PeriodicalCmds(params=add_cmds['periodical_cmds']).stop_cmds()
        if add_cmds['cmds_after_scenario']:
            OneShotCmds(params=add_cmds['cmds_after_scenario']).start_cmds()
